pub fn check_p61970_452_equipment_ap_con_complex_shacl_day_type_identified_object_name_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday", "Weekday", "Weekend", "All"];
    for mrid in dataset.by_type.get("DayType").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::DayType>() {
            Some(o) => o, None => continue,
        };
        if obj.base.name.is_empty() { continue; }
        if !ALLOWED.contains(&obj.base.name.as_str()) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq452:IdentifiedObject.name-validValues".to_string(),
                class:       "DayType".to_string(),
                property:    "IdentifiedObject.name".to_string(),
                message:     "Not valid value. The value is not one of the following values: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday, Weekday, Weekend, All.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:452:EQ:DayType.name:validValues".to_string(),
                description: "For DayType the name attribute indicates the days of the week that a given DayType represents. The name attribute is restricted to the following names: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday, Weekday, Weekend, All. If the name attribute is All, it represents all seven days of the week. If the name attribute is Weekday, it represents Monday through Friday. If the name attribute is Weekend, it represents Saturday and Sunday.".to_string(),
            });
        }
    }
    violations
}

