pub fn check_p61970_452_equipment_ap_con_complex_shacl_series_compensator_equipment_equipment_container_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("SeriesCompensator").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::SeriesCompensator>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.base.base.equipment_container.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["Line", "VoltageLevel", "DCConverterUnit"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "eq452:SeriesCompensator-containment".to_string(),
                    class:       "SeriesCompensator".to_string(),
                    property:    "Equipment.EquipmentContainer".to_string(),
                    message:     "The containment is either missing or it is not VoltageLevel, Line or DCConverterUnit.".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "C:452:EQ:SeriesCompensator:containment".to_string(),
                    description: "For SeriesCompensator the association Equipment.EquipmentContainer is required and shall point to EquipmentContainer of type VoltageLevel when in substation, DCConverterUnit or Line when outside substation.".to_string(),
                });
            }
        }
    }
    violations
}

pub fn check_p61970_452_equipment_ap_con_complex_shacl_solar_generating_unit_generating_unit_min_operati_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("SolarGeneratingUnit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::SolarGeneratingUnit>() {
            Some(o) => o, None => continue,
        };
        if obj.base.min_operating_p.is_none() || obj.base.max_operating_p.is_none() { continue; }
        if !((obj.base.min_operating_p.unwrap() as f64) <= obj.base.max_operating_p.unwrap() as f64) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq452:GeneratingUnit.minOperatingP-valueRangePair".to_string(),
                class:       "SolarGeneratingUnit".to_string(),
                property:    "GeneratingUnit.minOperatingP".to_string(),
                message:     "The value is greater than the value of GeneratingUnit.maxOperatingP.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:452:EQ:GeneratingUnit.minOperatingP:valueRangePair".to_string(),
                description: "GeneratingUnit.maxOperatingP shall be greater than or equal to GeneratingUnit.minOperatingP.".to_string(),
            });
        }
    }
    violations
}

